INSERT INTO feature VALUES('codata','types','Codata and copatterns',NULL,'implemented','notable',NULL,'Codata declared by its observations as a negative greatest-fixpoint former, read by those observations in the kernel and the core checker, its answers in the incremental log; the surface declaration, copatterns and the corpus owed. A coinductive datatype at the value universe is the positive former: the kernel reads its constructors as the final coalgebra, a case observes it one step at a time, a guarded fixpoint inhabits it, and no fold eliminates it.','kernel-core kernel-term core-term core-nbe core-checker core-incremental surface-lowering','crates/kernel-core/tests/codata.rs crates/kernel-core/tests/guard.rs crates/core-checker-base/tests/codata.rs crates/core-incremental/tests/native_formers.rs corpus/model/codata/streams.gandr corpus/pathological/codata/streams.gandr','corpus/model/codata/streams.gandr','#644');
